"""Cron-style schedules. SCHEDULE.md has the full rules."""

import bisect
import calendar
import datetime
import re

_MONTH_NAMES = {
    name: number
    for number, name in enumerate(
        ("JAN", "FEB", "MAR", "APR", "MAY", "JUN",
         "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"),
        start=1,
    )
}
_DOW_NAMES = {
    name: number
    for number, name in enumerate(
        ("SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT")
    )
}

_SHORTCUTS = {
    "@yearly": "0 0 1 1 *",
    "@annually": "0 0 1 1 *",
    "@monthly": "0 0 1 * *",
    "@weekly": "0 0 * * 0",
    "@daily": "0 0 * * *",
    "@midnight": "0 0 * * *",
    "@hourly": "0 * * * *",
}

_SPECS = {
    "minute": (0, 59, None),
    "hour": (0, 23, None),
    "dom": (1, 31, None),
    "month": (1, 12, _MONTH_NAMES),
    "dow": (0, 7, _DOW_NAMES),
}

_NUMBER = re.compile(r"[0-9]+")
_LAST_WEEKDAY = re.compile(r"([0-9]+)L")
_NTH_WEEKDAY = re.compile(r"([0-9]+)#([0-9]+)")


class _Field:
    __slots__ = ("values", "last", "last_weekdays", "nth_weekdays")

    def __init__(self, values, last=False, last_weekdays=(), nth_weekdays=()):
        self.values = frozenset(values)
        self.last = last
        self.last_weekdays = frozenset(last_weekdays)
        self.nth_weekdays = frozenset(nth_weekdays)


class _Schedule:
    __slots__ = ("minute", "hour", "dom", "month", "dow", "minutes", "hours")

    def __init__(self, minute, hour, dom, month, dow):
        self.minute = minute
        self.hour = hour
        self.dom = dom
        self.month = month
        self.dow = dow
        self.minutes = sorted(minute.values)
        self.hours = sorted(hour.values)


def _resolve(token, low, high, names, allow_names):
    if allow_names and names is not None and token.upper() in names:
        value = names[token.upper()]
    elif _NUMBER.fullmatch(token):
        value = int(token)
    else:
        raise ValueError(f"bad value {token!r}")
    if value < low or value > high:
        raise ValueError(f"value out of range: {token!r}")
    return value


def _parse_base(item, low, high, names, allow_names):
    if item == "*":
        return list(range(low, high + 1))
    if "-" in item:
        if item.count("-") != 1:
            raise ValueError(f"bad range: {item!r}")
        left, right = item.split("-")
        start = _resolve(left, low, high, names, allow_names)
        end = _resolve(right, low, high, names, allow_names)
        if start > end:
            raise ValueError(f"bad range: {item!r}")
        return list(range(start, end + 1))
    return [_resolve(item, low, high, names, allow_names)]


def _parse_field(text, kind):
    low, high, names = _SPECS[kind]

    if kind in ("dom", "dow") and text == "?":
        text = "*"

    values = set()
    last = False
    last_weekdays = set()
    nth_weekdays = set()

    for item in text.split(","):
        if not item:
            raise ValueError("empty item")

        if kind == "dom" and item == "L":
            last = True
            continue

        if kind == "dow":
            match = _LAST_WEEKDAY.fullmatch(item)
            if match:
                weekday = int(match.group(1))
                if weekday < 0 or weekday > 7:
                    raise ValueError(f"value out of range: {item!r}")
                last_weekdays.add(weekday % 7)
                continue

            match = _NTH_WEEKDAY.fullmatch(item)
            if match:
                weekday = int(match.group(1))
                occurrence = int(match.group(2))
                if weekday < 0 or weekday > 7:
                    raise ValueError(f"value out of range: {item!r}")
                if occurrence < 1 or occurrence > 5:
                    raise ValueError(f"value out of range: {item!r}")
                nth_weekdays.add((weekday % 7, occurrence))
                continue

        if "/" in item:
            if item.count("/") != 1:
                raise ValueError(f"bad step: {item!r}")
            base, step_text = item.split("/")
            if not _NUMBER.fullmatch(step_text):
                raise ValueError(f"bad step: {item!r}")
            step = int(step_text)
            if step < 1:
                raise ValueError(f"bad step: {item!r}")

            if base == "*":
                sequence = list(range(low, high + 1))
            else:
                sequence = _parse_base(base, low, high, names, False)
                if "-" not in base:
                    sequence = list(range(sequence[0], high + 1))
            values.update(sequence[::step])
        else:
            values.update(_parse_base(item, low, high, names, True))

    if kind == "dow":
        values = {value % 7 for value in values}
    return _Field(values, last, last_weekdays, nth_weekdays)


def _parse(expr):
    if not isinstance(expr, str):
        raise ValueError(f"bad schedule: {expr!r}")

    text = expr.strip()
    if not text:
        raise ValueError("empty schedule")

    if text.startswith("@"):
        shortcut = _SHORTCUTS.get(text.lower())
        if shortcut is None:
            raise ValueError(f"unknown shortcut: {text!r}")
        fields = shortcut.split()
    else:
        fields = re.split(r"[ \t]+", text)

    if len(fields) != 5:
        raise ValueError(f"wrong number of fields: {text!r}")

    minute = _parse_field(fields[0], "minute")
    hour = _parse_field(fields[1], "hour")
    dom = _parse_field(fields[2], "dom")
    month = _parse_field(fields[3], "month")
    dow = _parse_field(fields[4], "dow")
    return _Schedule(minute, hour, dom, month, dow)


def _day_matches(day, schedule):
    last_day = calendar.monthrange(day.year, day.month)[1]

    dom = schedule.dom
    if day.day not in dom.values and not (dom.last and day.day == last_day):
        return False

    dow = schedule.dow
    weekday = day.isoweekday() % 7

    if weekday in dow.values:
        return True
    if weekday in dow.last_weekdays and day.day + 7 > last_day:
        return True
    occurrence = (day.day - 1) // 7 + 1
    return (weekday, occurrence) in dow.nth_weekdays


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    schedule = _parse(expr)
    if when.minute not in schedule.minute.values:
        return False
    if when.hour not in schedule.hour.values:
        return False
    if when.month not in schedule.month.values:
        return False
    return _day_matches(when.date(), schedule)


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    schedule = _parse(expr)

    try:
        start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    except (OverflowError, ValueError):
        return None

    try:
        limit = after + datetime.timedelta(days=10 * 365)
    except OverflowError:
        limit = datetime.datetime.max

    day = start.date()
    first_day = day
    last_date = limit.date()

    while day <= last_date:
        if day.month in schedule.month.values and _day_matches(day, schedule):
            if day == first_day:
                hour_floor = start.hour
                minute_floor = start.minute
            else:
                hour_floor = 0
                minute_floor = 0

            index = bisect.bisect_left(schedule.hours, hour_floor)
            while index < len(schedule.hours):
                hour = schedule.hours[index]
                if hour > hour_floor:
                    minute = schedule.minutes[0]
                else:
                    minute_index = bisect.bisect_left(schedule.minutes, minute_floor)
                    if minute_index == len(schedule.minutes):
                        index += 1
                        continue
                    minute = schedule.minutes[minute_index]

                candidate = datetime.datetime.combine(
                    day, datetime.time(hour, minute)
                )
                if candidate <= limit:
                    return candidate
                return None

        if day == last_date:
            break
        day += datetime.timedelta(days=1)

    return None

